const item = $input.first();
const binary = item?.binary?.data;

if (!binary) {
  return [];
}

const raw = Buffer.from(binary, 'base64').toString('utf8');
let payload;

try {
  payload = JSON.parse(raw);
} catch (error) {
  throw new Error('Falha ao ler af_full_dump.json: ' + error.message);
}

const rows = Array.isArray(payload?.afsCompletas) ? payload.afsCompletas : [];

if (!rows.length) {
  return [];
}

return rows.map(row => ({ json: row }));

